method get_positive(l: seq<int>) returns (result: seq<int>)
    requires |l| > 0 // The list must have at least one element.
    ensures forall i :: 0 <= i < |result| ==> result[i] > 0 // All elements in the result are positive.
    ensures |result| <= |l| // The result cannot have more elements than the input list.
{
    var temp: seq<int> := [];
    var i: int := 0;
    while i < |l|
        invariant 0 <= i <= |l| // i is within the bounds of the list.
        invariant |temp| <= i // The number of positive numbers collected so far is at most i.
        invariant forall j :: 0 <= j < |temp| ==> temp[j] > 0 // All collected numbers in temp are positive.
    {
        if l[i] > 0 {
            temp := temp + [l[i]]; // Append the positive number to temp.
        }
        i := i + 1;
    }
    result := temp; // Assign the collected positive numbers to result.
}
```

